package org.telegram.ui.nebula;
import android.app.*;import android.os.Bundle;import android.content.*;import android.net.Uri;import android.widget.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;
/** User-initiated unencrypted JSON export/import via Android Storage Access Framework. */
public final class NebulaBackupActivity extends NebulaProtectedActivity {
 private static final int EXPORT=811,IMPORT=812;
 private static final String[] PREFS={"nebula_notes_local_v1","nebula_templates_local_v1","nebula_drafts_v1","nebula_bookmarks_v1","nebula_filter_rules_v1","nebula_features_v1"};
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout root=NebulaToolUi.page(this,"Nebula · Резервна копія","Експорт/імпорт локальних текстових даних і перемикачів. JSON НЕ зашифрований! Не містить PIN або вкладених файлів. Зберігайте копію в безпечному місці.");
 NebulaToolUi.button(this,root,"Експортувати JSON",()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,"nebula-backup.json");startActivityForResult(i,EXPORT);});
 NebulaToolUi.button(this,root,"Імпортувати JSON",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,IMPORT);});}
 private JSONObject snapshot()throws JSONException{JSONObject data=new JSONObject();data.put("format",1);for(String name:PREFS){JSONObject values=new JSONObject();for(java.util.Map.Entry<String,?> e:getSharedPreferences(name,0).getAll().entrySet()){Object v=e.getValue();if(v instanceof String||v instanceof Boolean||v instanceof Integer||v instanceof Long||v instanceof Float)values.put(e.getKey(),v);}data.put(name,values);}return data;}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();try{
 if(request==EXPORT){byte[] bytes=snapshot().toString(2).getBytes(StandardCharsets.UTF_8);try(OutputStream stream=getContentResolver().openOutputStream(uri,"w")){if(stream==null)throw new IOException("No stream");stream.write(bytes);}Toast.makeText(this,"Копію збережено",0).show();}
 if(request==IMPORT){ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("No stream");byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){if(bytes.size()+n>2_000_000)throw new IOException("Файл завеликий");bytes.write(buf,0,n);}}JSONObject backup=new JSONObject(bytes.toString("UTF-8"));if(backup.optInt("format",-1)!=1)throw new JSONException("Невідомий формат");
 new AlertDialog.Builder(this).setTitle("Імпортувати дані?").setMessage("Поточні локальні записи з цих розділів буде замінено. PIN і файли не зміняться.").setNegativeButton("Скасувати",null).setPositiveButton("Імпортувати",(d,w)->{try{for(String name:PREFS){JSONObject values=backup.optJSONObject(name);if(values==null)continue;SharedPreferences.Editor editor=getSharedPreferences(name,0).edit().clear();java.util.Iterator<String> keys=values.keys();while(keys.hasNext()){String k=keys.next();Object v=values.opt(k);if(v instanceof Boolean)editor.putBoolean(k,(Boolean)v);else if(v instanceof Integer)editor.putInt(k,(Integer)v);else if(v instanceof Long)editor.putLong(k,(Long)v);else if(v instanceof Double)editor.putFloat(k,((Double)v).floatValue());else if(v instanceof String)editor.putString(k,(String)v);}if(!editor.commit())throw new IOException("Cannot save "+name);}Toast.makeText(this,"Імпорт завершено",0).show();}catch(Exception e){Toast.makeText(this,"Помилка імпорту: "+e.getMessage(),1).show();}}).show();}
 }catch(Exception e){Toast.makeText(this,"Помилка: "+e.getMessage(),1).show();}}
}
